{
  "components": [
    {
      "type": "claim",
      "quote": "RailCom monitors compliance with the principles of non-discrimination and transparency.",
      "gist": "RailCom oversees adherence to non-discrimination and transparency principles."
    },
    {
      "type": "claim",
      "quote": "RailCom was established as part of the 1999 railways reform, which mainly sought to introduce free access to the railway network.",
      "gist": "RailCom was created during the 1999 railway reform to promote network access."
    },
    {
      "type": "entity",
      "quote": "Independent Complaints Authority for Radio and Television ICA",
      "gist": "ICA is the Independent Complaints Authority for Radio and Television."
    },
    {
      "type": "claim",
      "quote": "The Independent Complaints Authority for Radio and Television (ICA) handles complaints relating to radio and television programmes by the SRG and private broadcasters.",
      "gist": "ICA manages complaints about radio and TV programs from SRG and private broadcasters."
    },
    {
      "type": "claim",
      "quote": "The ICA seeks to determine possible breaches of the law in editorial broadcasts or unlawful refusal of the right to appear on a programme.",
      "gist": "ICA investigates potential legal violations in broadcasts or unlawful appearance denials."
    }
  ]
}
